//! `McpHandler` — the `rmcp` `ServerHandler` implementation for localdb.
//!
//! Tool routing (`tools/list`, `tools/call`) is entirely macro-generated by
//! `#[tool_router]`/`#[tool_handler]`; there is no hand-written dispatch
//! table. Each `#[tool]` method here resolves the caller's `Principal`
//! (see below), resolves the current store list via `self.provider`
//! (realtime — see `store_provider.rs`), and then forwards to a `tools::*`
//! fn — all validation and business logic lives in `tools.rs`, which keeps
//! its pure `&[AvailableStore]` signatures unchanged.
//!
//! ## Principal resolution (specs/05-surfaces.md §4, T3)
//!
//! On the HTTP transport, rmcp's `StreamableHttpService` injects the
//! request's remaining `http::request::Parts` into the tool call's
//! `RequestContext.extensions`; `Parts.extensions` in turn carries whatever
//! the daemon's axum `require_auth` middleware inserted — including the
//! authenticated `Principal`. `default_principal` covers the transports
//! with no HTTP request at all:
//!
//! - embedded stdio (`localdb mcp`, no daemon): `Some(local_trust)` — the
//!   caller is already trusted as local-files-equivalent (D8);
//! - daemon in open mode: `Some(local_trust)` (the middleware inserts it on
//!   each request anyway; the default keeps construction uniform);
//! - daemon with auth **enforced**: `None`, so a missing request-extension
//!   `Principal` is an authentication error (fail closed) — never full
//!   access.
//!
//! T3 interim policy: admins (and `local_trust`) pass; `member` principals
//! get a `forbidden` tool error on every tool. T5 replaces the member gate
//! with store-grant filtering (D7).

use std::sync::Arc;

use rmcp::{
    handler::server::{router::tool::ToolRouter, wrapper::Parameters},
    model::{CallToolResult, Extensions, Implementation, ServerCapabilities, ServerInfo},
    service::RequestContext,
    tool, tool_handler, tool_router, RoleServer, ServerHandler,
};

use localdb_core::{
    auth::{Principal, Role},
    Embedder, Error,
};

use crate::args::{GetChunksArgs, GetDocumentArgs, SearchArgs};
use crate::store_provider::StoreProvider;
use crate::tools::{self, AvailableStore};

/// Convert a `StoreProvider::available_stores` failure into a tool-level MCP
/// error result, so a broken/unavailable store backend surfaces as a normal
/// `CallToolResult { is_error: Some(true), .. }` rather than a panic — the
/// service itself stays up and can serve the next call.
fn provider_error(e: &Error) -> CallToolResult {
    tools::typed_error(e.code(), format!("failed to resolve available stores: {e}"))
}

/// Embedded-stdio / HTTP MCP server handler: holds a `StoreProvider` (stores
/// are resolved fresh on every tool call, not snapshotted at construction —
/// see `store_provider.rs`), the embedder used for `search`, whether
/// `--allow-write` was passed (parsed but always rejected in v1 — no
/// mutating tool is registered), and the fallback `Principal` for
/// transports that carry no per-request identity (see the module doc).
#[derive(Clone)]
pub struct McpHandler {
    pub provider: Arc<dyn StoreProvider>,
    pub embedder: Arc<dyn Embedder>,
    pub allow_write: bool,
    default_principal: Option<Principal>,
    tool_router: ToolRouter<Self>,
}

impl McpHandler {
    /// Create a new handler over the given store provider and embedder.
    ///
    /// `default_principal` is used when the request context carries no
    /// `Principal` (see the module doc): pass `Some(Principal::local_trust())`
    /// for embedded stdio and open-mode daemons, `None` when the daemon
    /// enforces auth so a missing principal fails closed.
    pub fn new(
        provider: Arc<dyn StoreProvider>,
        embedder: Arc<dyn Embedder>,
        allow_write: bool,
        default_principal: Option<Principal>,
    ) -> Self {
        Self {
            provider,
            embedder,
            allow_write,
            default_principal,
            tool_router: Self::tool_router(),
        }
    }

    /// Resolve the caller's `Principal` for this tool call (R4).
    ///
    /// Takes the call's `rmcp::model::Extensions` (from
    /// `RequestContext.extensions`) rather than the whole context so the
    /// resolution path is unit-testable — `RequestContext` cannot be
    /// constructed outside rmcp (its `Peer::new` is `pub(crate)`), but
    /// `Extensions` can.
    ///
    /// Priority:
    /// 1. A `Principal` in the HTTP request extensions, reached through the
    ///    `http::request::Parts` rmcp injects into
    ///    `RequestContext.extensions` on the Streamable HTTP transport —
    ///    this is what the daemon's `require_auth` middleware inserted.
    /// 2. A `Principal` directly in the rmcp extensions (not produced by
    ///    any current transport; checked for completeness).
    /// 3. `self.default_principal` (embedded stdio / open mode).
    /// 4. Otherwise: fail closed with an `unauthorized` tool error — on an
    ///    enforced-auth daemon a missing extension means the auth layer was
    ///    bypassed, and answering with full access would be privilege
    ///    escalation.
    fn principal_for(&self, extensions: &Extensions) -> Result<Principal, CallToolResult> {
        if let Some(parts) = extensions.get::<http::request::Parts>() {
            if let Some(principal) = parts.extensions.get::<Principal>() {
                return Ok(principal.clone());
            }
        }
        if let Some(principal) = extensions.get::<Principal>() {
            return Ok(principal.clone());
        }
        match &self.default_principal {
            Some(principal) => Ok(principal.clone()),
            None => Err(tools::typed_error(
                "unauthorized",
                "no authenticated principal on this request; the MCP endpoint requires a \
                 valid bearer token",
            )),
        }
    }

    /// T3 interim authorization: resolve the principal and reject members
    /// wholesale. T5 lifts this by filtering tool results by store grants
    /// (D7) instead.
    fn require_authorized(&self, extensions: &Extensions) -> Result<Principal, CallToolResult> {
        let principal = self.principal_for(extensions)?;
        if principal.role == Role::Member {
            return Err(tools::typed_error(
                "forbidden",
                format!(
                    "user '{}' has role 'member'; member access to MCP tools activates with \
                     store grants in a later release",
                    principal.name
                ),
            ));
        }
        Ok(principal)
    }

    /// Resolve the current store list, or `None` (having already produced
    /// the tool-error result) on provider failure.
    async fn resolve_stores(&self) -> Result<Vec<AvailableStore>, CallToolResult> {
        self.provider
            .available_stores()
            .await
            .map_err(|e| provider_error(&e))
    }

    /// Shared per-tool preamble: authorize the caller, then resolve stores.
    async fn authorize_and_resolve(
        &self,
        extensions: &Extensions,
    ) -> Result<Vec<AvailableStore>, CallToolResult> {
        self.require_authorized(extensions)?;
        self.resolve_stores().await
    }

    // The `*_inner` methods below carry the full tool behavior against a
    // bare `Extensions`; the `#[tool]` wrappers only peel it off the
    // `RequestContext`. Unit tests drive the inner methods directly
    // (`RequestContext` is not constructible outside rmcp); the
    // wrapper→inner hop plus rmcp's own extension propagation is covered by
    // the end-to-end test in `server/tests/` (R4).

    async fn search_inner(&self, args: SearchArgs, extensions: &Extensions) -> CallToolResult {
        let stores = match self.authorize_and_resolve(extensions).await {
            Ok(s) => s,
            Err(result) => return result,
        };
        tools::tool_search(&stores, self.embedder.as_ref(), args).await
    }

    async fn get_document_inner(
        &self,
        args: GetDocumentArgs,
        extensions: &Extensions,
    ) -> CallToolResult {
        let stores = match self.authorize_and_resolve(extensions).await {
            Ok(s) => s,
            Err(result) => return result,
        };
        tools::tool_get_document(&stores, args).await
    }

    async fn get_chunks_inner(
        &self,
        args: GetChunksArgs,
        extensions: &Extensions,
    ) -> CallToolResult {
        let stores = match self.authorize_and_resolve(extensions).await {
            Ok(s) => s,
            Err(result) => return result,
        };
        tools::tool_get_chunks(&stores, args).await
    }

    async fn list_stores_inner(&self, extensions: &Extensions) -> CallToolResult {
        let stores = match self.authorize_and_resolve(extensions).await {
            Ok(s) => s,
            Err(result) => return result,
        };
        tools::tool_list_stores(&stores).await
    }
}

#[tool_router]
impl McpHandler {
    /// Hybrid search (BM25 + dense vector) across indexed stores. Returns a
    /// ranked list of citations in the canonical localdb Citation JSON shape.
    #[tool(
        description = "Hybrid search (BM25 + dense vector) across indexed stores. Returns a ranked list of citations in the canonical localdb Citation JSON shape."
    )]
    async fn search(
        &self,
        Parameters(args): Parameters<SearchArgs>,
        ctx: RequestContext<RoleServer>,
    ) -> CallToolResult {
        self.search_inner(args, &ctx.extensions).await
    }

    /// Fetch the normalized text and metadata for a document by its ID.
    #[tool(description = "Fetch the normalized text and metadata for a document by its ID or URI.")]
    async fn get_document(
        &self,
        Parameters(args): Parameters<GetDocumentArgs>,
        ctx: RequestContext<RoleServer>,
    ) -> CallToolResult {
        self.get_document_inner(args, &ctx.extensions).await
    }

    /// Fetch a document's chunks in order, paginated by offset/limit.
    #[tool(
        description = "Fetch a document's chunks in order (block_seq, seq_in_block), paginated by offset/limit."
    )]
    async fn get_chunks(
        &self,
        Parameters(args): Parameters<GetChunksArgs>,
        ctx: RequestContext<RoleServer>,
    ) -> CallToolResult {
        self.get_chunks_inner(args, &ctx.extensions).await
    }

    /// List all available stores with their names, visibility, and
    /// document/chunk counts.
    #[tool(
        description = "List all available stores with their names, visibility, and document/chunk counts."
    )]
    async fn list_stores(&self, ctx: RequestContext<RoleServer>) -> CallToolResult {
        self.list_stores_inner(&ctx.extensions).await
    }
}

// `router = self.tool_router` reuses the stored instance field rather than
// rebuilding a fresh router via `Self::tool_router()` on every call (rmcp's
// default when no `router = ...` is given) — the field would otherwise be
// dead weight per rustc's dead-code lint, and reconstructing it per-call is
// wasted work for a routing table that never changes at runtime.
#[tool_handler(router = self.tool_router)]
impl ServerHandler for McpHandler {
    fn get_info(&self) -> ServerInfo {
        ServerInfo::new(ServerCapabilities::builder().enable_tools().build())
            .with_server_info(Implementation::new("localdb", env!("CARGO_PKG_VERSION")))
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::store_provider::StaticStoreProvider;
    use async_trait::async_trait;
    use localdb_core::auth::StoreAccess;
    use localdb_core::embedder::FakeEmbedder;

    /// A `StoreProvider` that always fails, to prove a provider error
    /// surfaces as a tool-level MCP error (not a panic) and the handler
    /// remains usable afterward.
    struct ErrorStoreProvider;

    #[async_trait]
    impl StoreProvider for ErrorStoreProvider {
        async fn available_stores(&self) -> Result<Vec<AvailableStore>, Error> {
            Err(Error::Internal {
                message: "backend unavailable".to_string(),
                correlation_id: "test_provider_error".to_string(),
            })
        }
    }

    fn embedder() -> Arc<dyn Embedder> {
        Arc::new(FakeEmbedder::new(4))
    }

    /// Empty rmcp extensions — what an embedded stdio call looks like (no
    /// HTTP `Parts`, no injected `Principal`).
    fn no_extensions() -> Extensions {
        Extensions::default()
    }

    /// Extensions carrying `principal` the way the daemon's HTTP path does:
    /// inside the request extensions of the `http::request::Parts` rmcp
    /// injects into `RequestContext.extensions`.
    fn http_extensions_with_principal(principal: Principal) -> Extensions {
        let mut extensions = Extensions::default();
        let (mut parts, _body) = http::Request::new(()).into_parts();
        parts.extensions.insert(principal);
        extensions.insert(parts);
        extensions
    }

    fn member(name: &str) -> Principal {
        Principal {
            user_id: format!("uid-{name}"),
            name: name.to_string(),
            role: Role::Member,
            access: StoreAccess::Granted(Default::default()),
        }
    }

    fn error_code(result: &CallToolResult) -> String {
        let text = result.content[0].as_text().unwrap().text.clone();
        let parsed: serde_json::Value = serde_json::from_str(&text).expect("must be JSON");
        parsed["error"]["code"].as_str().unwrap().to_string()
    }

    #[tokio::test]
    async fn list_stores_returns_tool_error_when_provider_fails() {
        let handler = McpHandler::new(
            Arc::new(ErrorStoreProvider),
            embedder(),
            false,
            Some(Principal::local_trust()),
        );
        let result = handler.list_stores_inner(&no_extensions()).await;
        assert_eq!(result.is_error, Some(true));
        let text = result.content[0].as_text().unwrap().text.clone();
        let parsed: serde_json::Value = serde_json::from_str(&text).expect("must be JSON");
        assert_eq!(parsed["error"]["code"].as_str().unwrap(), "internal");
        assert!(parsed["error"]["message"]
            .as_str()
            .unwrap()
            .contains("backend unavailable"));
    }

    #[tokio::test]
    async fn handler_stays_usable_after_a_provider_error() {
        let handler = McpHandler::new(
            Arc::new(ErrorStoreProvider),
            embedder(),
            false,
            Some(Principal::local_trust()),
        );

        let first = handler.list_stores_inner(&no_extensions()).await;
        assert_eq!(first.is_error, Some(true));

        // The service must not have panicked or otherwise become unusable —
        // a second call against the same (still-failing) provider still
        // produces a clean tool-level error, not a crash.
        let second = handler.list_stores_inner(&no_extensions()).await;
        assert_eq!(second.is_error, Some(true));
    }

    #[tokio::test]
    async fn list_stores_succeeds_once_provider_recovers() {
        // Same handler *shape* as the static case — proves a working
        // provider still round-trips normally through `resolve_stores`.
        let provider = Arc::new(StaticStoreProvider::new(vec![]));
        let handler = McpHandler::new(provider, embedder(), false, Some(Principal::local_trust()));
        let result = handler.list_stores_inner(&no_extensions()).await;
        assert_ne!(result.is_error, Some(true));
    }

    // --- Principal resolution (R4, fail-closed) ---

    #[tokio::test]
    async fn no_principal_and_no_default_fails_closed() {
        // Enforced-HTTP construction: default_principal = None. A context
        // with no injected Principal must produce an unauthorized tool
        // error — never full access.
        let provider = Arc::new(StaticStoreProvider::new(vec![]));
        let handler = McpHandler::new(provider, embedder(), false, None);
        let result = handler.list_stores_inner(&no_extensions()).await;
        assert_eq!(result.is_error, Some(true));
        assert_eq!(error_code(&result), "unauthorized");
    }

    #[tokio::test]
    async fn http_injected_admin_principal_is_used() {
        // Even with no default (enforced mode), a Principal delivered via
        // http::request::Parts extensions authorizes the call.
        let provider = Arc::new(StaticStoreProvider::new(vec![]));
        let handler = McpHandler::new(provider, embedder(), false, None);
        let result = handler
            .list_stores_inner(&http_extensions_with_principal(Principal::local_trust()))
            .await;
        assert_ne!(result.is_error, Some(true));
    }

    #[tokio::test]
    async fn member_principal_gets_forbidden_tool_error() {
        // T3 interim policy: members are rejected on every tool (grants
        // activate in T5).
        let provider = Arc::new(StaticStoreProvider::new(vec![]));
        let handler = McpHandler::new(provider, embedder(), false, None);
        let result = handler
            .list_stores_inner(&http_extensions_with_principal(member("bob")))
            .await;
        assert_eq!(result.is_error, Some(true));
        assert_eq!(error_code(&result), "forbidden");
    }

    #[tokio::test]
    async fn default_local_trust_authorizes_embedded_calls() {
        // Embedded stdio: no HTTP Parts at all; default local_trust applies.
        let provider = Arc::new(StaticStoreProvider::new(vec![]));
        let handler = McpHandler::new(provider, embedder(), false, Some(Principal::local_trust()));
        let result = handler.list_stores_inner(&no_extensions()).await;
        assert_ne!(result.is_error, Some(true));
    }

    #[tokio::test]
    async fn member_default_principal_is_also_gated() {
        // Nothing constructs this today, but the member gate must hold no
        // matter how the principal arrived.
        let provider = Arc::new(StaticStoreProvider::new(vec![]));
        let handler = McpHandler::new(provider, embedder(), false, Some(member("carol")));
        let result = handler.list_stores_inner(&no_extensions()).await;
        assert_eq!(result.is_error, Some(true));
        assert_eq!(error_code(&result), "forbidden");
    }
}
